// 异常的四个要素：对象、抛出、传播、捕获
public class ExceptionFlow {
    static int divide(int a, int b) {
        if (b == 0) {
            throw new ArithmeticException("除数不能为零");   // 一、创建异常对象并抛出
        }
        return a / b;
    }

    public static void main(String[] args) {
        try {
            int r = divide(10, 0);      // 三、异常沿调用栈传播到这里
            System.out.println(r);      // 这行不会执行
        } catch (ArithmeticException e) {   // 四、捕获
            System.out.println("算不出来：" + e.getMessage());
        }
        System.out.println("程序继续正常运行");   // 抛出异常不等于程序崩溃
    }
}

