// 一个可以直接抄的自定义异常模板
public class BizException extends RuntimeException {
    private static final long serialVersionUID = 1L;   // 跨进程传递时需要

    private final ErrorCode errorCode;                 // 错误码枚举
    private final String requestId;                    // 追踪用

    public BizException(ErrorCode code) {
        this(code, code.getMessage(), null, null);
    }

    public BizException(ErrorCode code, String message) {
        this(code, message, null, null);
    }

    public BizException(ErrorCode code, String message, Throwable cause) {
        this(code, message, cause, null);
    }

    public BizException(ErrorCode code, String message, Throwable cause, String requestId) {
        super(message == null ? code.getMessage() : message, cause);  // cause 必须传
        this.errorCode = code;
        this.requestId = requestId;
    }

    public ErrorCode getErrorCode() { return errorCode; }
    public String getRequestId() { return requestId; }
}

