// 一个健壮的根因提取工具，带环检测与深度限制
public static Throwable getRootCause(Throwable t) {
    if (t == null) return null;
    Throwable cur = t;
    for (int depth = 0; depth < 50; depth++) {          // 深度上限，防止异常的环
        Throwable next = cur.getCause();
        if (next == null || next == cur) {              // 没有上一层，或者指向自己
            return cur;
        }
        cur = next;
    }
    return cur;                                        // 超过 50 层就直接返回，防御性收尾
}

// 用法：日志打完整链，监控记根因类型
catch (Exception e) {
    Throwable root = getRootCause(e);
    log.error("下单失败 orderId={}, rootCause={}", orderId, root.getClass().getName(), e);
    metrics.counter("order.fail." + root.getClass().getSimpleName()).increment();
    throw new BizException(ErrorCode.ORDER_FAIL, "下单失败", e);
}

// 手写 finally 也保留主次关系（老代码的正确姿势）
IOException primary = null;
InputStream in = null;
try {
    in = new FileInputStream(file);
    in.read(buffer);
} catch (IOException e) {
    primary = e;
    throw e;
} finally {
    if (in != null) {
        try {
            in.close();
        } catch (IOException closeEx) {
            if (primary != null) {
                primary.addSuppressed(closeEx);   // 主异常优先，关闭异常挂上去
            } else {
                throw closeEx;                    // 没有主异常，close 失败就是主异常
            }
        }
    }
}

