// 编译器大致展开成这样（去掉异常表细节）
InputStream in = new FileInputStream(f);
Throwable primary = null;
try {
    in.read(buffer);
} catch (Throwable t) {
    primary = t;
    throw t;
} finally {
    if (in != null) {
        if (primary != null) {
            try {
                in.close();
            } catch (Throwable closeEx) {
                primary.addSuppressed(closeEx);    // 关键：不覆盖主异常
            }
        } else {
            in.close();                            // 没有主异常，close 异常直接抛
        }
    }
}

