// 经典陷阱：finally 改不动返回值
public static int test1() {
    int x = 10;
    try {
        return x;        // 步骤一：x 的值 10 被存入临时槽
    } finally {
        x = 20;          // 步骤二：改的是变量 x，临时槽里还是 10
    }                    // 步骤三：返回临时槽里的 10
}

