// 泄漏版本：异常路径下连接不还
public Order find(long id) {
    Connection conn = dataSource.getConnection();       // 借出
    try {
        PreparedStatement ps = conn.prepareStatement("select * from orders where id=?");
        ps.setLong(1, id);
        ResultSet rs = ps.executeQuery();
        return map(rs);
    } catch (SQLException e) {
