// 十条清单的可执行版本：抽成一个检查表，评审时逐条勾
// 1. 方法签名诚实：不存在「返回 null 表示失败」
// 2. catch 有意义：处理 / 转换 / 记录并上抛
// 3. cause 完整：throw new 时带上了捕获的异常
// 4. 资源配对：所有资源都在 try-with-resources 里
// 5. finally 干净：只有清理，没有 return
// 6. 异常不做控制流：高频分支改返回值
// 7. 日志不重复：谁处理谁记录
// 8. 不过宽捕获：业务代码不用 catch (Exception)
// 9. 自定义异常可用：有 cause 构造器、有错误码、消息可读
// 10. 异步有归宿：每个异步任务都有异常处理路径

// 一个符合全部十条的模板方法
public Order load(long id) {
    if (id <= 0) {
        throw new IllegalArgumentException("订单 id 必须为正数：" + id);   // 快速失败，标准异常
    }
    try (Connection conn = ds.getConnection();
         PreparedStatement ps = conn.prepareStatement(SQL)) {
        ps.setLong(1, id);
        try (ResultSet rs = ps.executeQuery()) {
            return rs.next() ? map(rs) : null;   // 真的没有，返回 null 并在文档说明
        }
    } catch (SQLException e) {
        throw new BizException(ErrorCode.QUERY_FAIL, "查询订单失败 id=" + id, e);  // 保留 cause
    }
}

